package app.filmmerkezi.tv.core

import org.json.*

/** Internal native adapter compatibility v1. Public third-party SDK stays JSON-only. */
object PluginWire {
    private fun JSONObject.items(name:String)=optJSONArray(name)?.let{a->(0 until a.length()).map{a.getJSONObject(it)}}?:emptyList()
    private fun JSONObject.strings(name:String)=optJSONArray(name)?.let{a->(0 until a.length()).map{a.getString(it)}}?:emptyList()
    private fun JSONObject.map(name:String)=optJSONObject(name)?.let{o->o.keys().asSequence().associateWith{o.getString(it)}}?:emptyMap()
    fun site(s:SiteSpec)=JSONObject().put("id",s.id).put("name",s.name).put("base",s.base).put("search",s.search).put("list",s.list).put("cards",s.cards).put("title",s.title).put("detailTitle",s.detailTitle).put("description",s.description).put("poster",s.poster).put("year",s.year).put("imdb",s.imdb).put("language",s.language).put("seriesPath",s.seriesPath?:JSONObject.NULL).put("contentPattern",s.contentPattern.pattern).put("episodeSelector",s.episodeSelector).put("genres",s.genres).put("catalogAliases",JSONArray(s.catalogAliases.toList()))
    fun site(o:JSONObject)=SiteSpec(o.getString("id"),o.getString("name"),o.getString("base"),o.optString("search","/?s="),o.optString("list","/"),o.optString("cards","a.poster"),o.optString("title","h2"),o.optString("detailTitle","h1"),o.optString("description","[itemprop=description]"),o.optString("poster","img"),o.optString("year",".year"),o.optString("imdb",".imdb"),o.optString("language",".language"),if(o.isNull("seriesPath"))null else o.optString("seriesPath").ifBlank{null},Regex(o.optString("contentPattern","^/[^/]+/$")),o.optString("episodeSelector","a[href*=bolum]"),o.optString("genres","[itemprop=genre]"),o.strings("catalogAliases").toSet())
    fun ref(o:JSONObject)=ContentRef(o.getString("siteId"),o.getString("pageUrl"),ContentKind.valueOf(o.getString("kind").uppercase()))
    fun cursor(o:JSONObject)=PageCursor(o.getString("siteId"),o.getString("url"),o.optInt("page",2),o.map("fields"))
    fun option(o:JSONObject)=SourceOption(o.getString("id"),ref(o.getJSONObject("content")),o.getString("label"),o.getString("url"),o.optString("extractor"),OptionState.valueOf(o.optString("state","available").uppercase()),o.optString("reason"),o.map("fields"))
    fun query(q:CatalogQuery)=JSONObject().put("kind",q.kind.name).put("genre",q.genre).put("year",q.year?:JSONObject.NULL).put("language",q.language).put("minRating",q.minRating).put("order",q.order.name)
    fun query(o:JSONObject)=CatalogQuery(ContentKind.valueOf(o.getString("kind")),o.optString("genre"),if(o.isNull("year"))null else o.getInt("year"),o.optString("language"),o.optDouble("minRating",0.0),CatalogOrder.valueOf(o.optString("order","DEFAULT")))
    fun options(v:FilterOptions)=JSONObject().put("values",JSONObject().apply{v.values.forEach{(k,rows)->put(k,JSONArray(rows.map{JSONObject().put("value",it.value).put("label",it.label)}))}})
    fun options(o:JSONObject):FilterOptions {val v=o.getJSONObject("values");return FilterOptions(v.keys().asSequence().associateWith{k->v.items(k).map{FilterValue(it.getString("value"),it.getString("label"))}})}
    fun page(v:CatalogPage)=JSONObject().put("cards",JSONArray(v.cards.map(Contracts::card))).put("next",v.next?.let(Contracts::cursor)?:JSONObject.NULL).apply{v.coverage?.let{put("coverage",JSONObject().put("siteId",it.siteId).put("remote",JSONArray(it.remote.toList())).put("local",JSONArray(it.local.toList())).put("checked",it.checked).put("omitted",it.omitted))}}
    fun page(o:JSONObject)=CatalogPage(o.items("cards").map(Contracts::readCard),o.optJSONObject("next")?.let(::cursor),o.optJSONObject("coverage")?.let{FilterCoverage(it.getString("siteId"),it.strings("remote").toSet(),it.strings("local").toSet(),it.optInt("checked"),it.optInt("omitted"))})
    fun episode(e:Episode)=JSONObject().put("card",Contracts.card(e.card)).put("series",Contracts.ref(e.series)).put("season",e.number.season).put("number",e.number.number).put("description",e.description).put("alternatives",JSONArray(e.alternatives.map(Contracts::card)))
    fun episode(o:JSONObject)=Episode(Contracts.readCard(o.getJSONObject("card")),ref(o.getJSONObject("series")),EpisodeNumber(o.getInt("season"),o.getInt("number")),o.optString("description"),o.items("alternatives").map(Contracts::readCard))
    fun detail(v:Detail)=Contracts.detail(v).put("cast",JSONArray(v.cast)).put("duration",v.duration).put("episodes",JSONArray(v.episodes.map(::episode))).put("collectionItems",JSONArray(v.collectionItems.map{JSONObject().put("title",it.title).put("year",it.year).put("ordinal",it.ordinal).put("aliases",JSONArray(it.aliases))})).put("seasons",JSONArray(v.seasons))
    fun detail(o:JSONObject)=Detail(Contracts.readCard(o.getJSONObject("card")),o.optString("description"),o.strings("genres"),o.strings("cast"),o.optString("duration"),o.items("episodes").map(::episode),o.strings("episodePages"),o.items("options").map(::option),o.optJSONObject("episodesNext")?.let(::cursor),o.items("collectionItems").mapIndexed{i,v->CollectionEntry(v.optInt("ordinal",i),v.getString("title"),v.getInt("year"),v.strings("aliases"))},o.optJSONArray("seasons")?.let{a->(0 until a.length()).map{a.getInt(it)}}?:emptyList())
    fun source(o:JSONObject):ResolvedSource {
        fun audio(a:JSONObject)=MediaAudio(a.getString("url"),a.optString("language"),a.optString("label"),a.optString("mimeType","audio/mp4"))
        return ResolvedSource(o.getString("id"),o.getString("label"),o.getString("url"),StreamType.valueOf(o.getString("type").uppercase()),o.optString("referer"),o.optString("userAgent"),o.optString("cookie"),o.map("headers"),o.items("subtitles").map{Subtitle(it.getString("url"),it.optString("label"),it.optString("language"),it.optString("format","vtt"))},o.strings("playbackRequirements").toSet(),o.optJSONObject("mediaProfile")?.let{MediaProfile(it.optString("videoCodec").ifBlank{null},it.optString("audioCodec").ifBlank{null},it.optInt("width").takeIf{n->n>0},it.optInt("height").takeIf{n->n>0})},o.optLong("expiresAt").takeIf{it>0},o.items("audioStreams").map(::audio),o.items("variants").map{MediaVariant(it.getString("id"),it.getString("url"),it.getInt("height"),it.optInt("width"),it.items("audioStreams").map(::audio),it.optString("codec"),it.optInt("fps"),it.optString("mimeType","video/mp4"))},o.items("sessionCookies").map{SessionCookie(it.getString("name"),it.getString("value"),it.getString("domain"),it.getString("path"),it.getLong("expiresAt"),it.getBoolean("secure"),it.getBoolean("httpOnly"),it.getBoolean("hostOnly"))})
    }
}
